/**
 * FR-D4 — the global print pipeline.
 *
 * This is the **only** component in the application that renders a printable
 * page. Report cards, class lists, permits, registers and every future export
 * go through `<Sheet>`, which stamps the institution's name and logo into the
 * header and "Generated by Results Manager" plus the page number and print date
 * into the footer.
 *
 * There is no prop for a sponsor name or third-party attribution, and no way to
 * suppress the header or the footer — FR-D4 says no requirement may bypass this
 * pipeline, so the component gives no bypass to use.
 */

import type { CSSProperties, ReactNode } from "react";
import {
  Bath,
  BookOpen,
  Calculator,
  Ear,
  HandHeart,
  HeartPulse,
  type LucideIcon,
  MessageCircle,
  Mic,
  Music,
  Palette,
  PenLine,
  Printer,
  Puzzle,
  Shapes,
  Smile,
  Star,
  Toilet,
  Users,
  Volleyball,
} from "lucide-react";

import type {
  Branding,
  ClassListBody,
  DocumentEnvelope,
  Footer,
  IdCard,
  IdCardBatch,
  PassOutSlip,
  ReportCard,
  Rating,
  ReportCardBatch,
} from "../lib/types";
import { Button } from "./ui";

// ---------------------------------------------------------------------------
// The sheet
// ---------------------------------------------------------------------------

interface SheetProps {
  branding: Branding;
  footer: Footer;
  title: string;
  subtitle?: ReactNode;
  landscape?: boolean;
  /** The nursery card's brighter layout. Branding and footer are unchanged. */
  variant?: "standard" | "nursery" | "compact";
  /** Drawn at the header's right edge, e.g. the learner's photo. */
  aside?: ReactNode;
  pageNumber: number;
  pageCount: number;
  children: ReactNode;
}

function Sheet({
  branding,
  footer,
  title,
  subtitle,
  landscape = false,
  variant = "standard",
  aside,
  pageNumber,
  pageCount,
  children,
}: SheetProps) {
  const contact = [branding.address, branding.phone, branding.email]
    .filter(Boolean)
    .join("  •  ");

  const className = [
    "sheet",
    landscape && "sheet-landscape",
    variant === "nursery" && "sheet-nursery",
    variant === "compact" && "sheet-compact",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <article
      className={className}
      style={{ "--doc-accent": branding.accentColor } as CSSProperties}
    >
      {/* --- Institution branding. Never anything else. --- */}
      <header className="doc-head">
        {branding.logoDataUrl ? (
          <img className="doc-logo" src={branding.logoDataUrl} alt="" />
        ) : (
          <div className="doc-logo-placeholder">No logo</div>
        )}

        <div className="doc-identity">
          <div className="doc-institution">{branding.institutionName}</div>
          {branding.motto && <div className="doc-motto">“{branding.motto}”</div>}
          {contact && <div className="doc-contact">{contact}</div>}
        </div>

        {aside ?? (
          // Balances the logo so the name stays optically centred.
          <div className="doc-logo-placeholder" style={{ visibility: "hidden" }} />
        )}
      </header>

      <div className="doc-title">{title}</div>
      {subtitle && <div className="doc-subtitle">{subtitle}</div>}

      <div className="doc-body">{children}</div>

      {/* --- Fixed footer, per FR-D4. --- */}
      <footer className="doc-foot">
        <span>{footer.generatedBy}</span>
        <span>
          Page {pageNumber} of {pageCount}
        </span>
        <span>Printed {footer.printedOn}</span>
      </footer>
    </article>
  );
}

// ---------------------------------------------------------------------------
// Preview frame (screen only — hidden at print time)
// ---------------------------------------------------------------------------

export function PrintPreview({
  actions,
  children,
}: {
  actions?: ReactNode;
  children: ReactNode;
}) {
  return (
    <div className="print-root">
      <div className="print-toolbar no-print">
        <Button
          variant="primary"
          icon={<Printer size={15} />}
          onClick={() => window.print()}
        >
          Print
        </Button>
        {actions}
      </div>
      {children}
    </div>
  );
}

// ---------------------------------------------------------------------------
// FR-D1 — report card
// ---------------------------------------------------------------------------

export function ReportCardSheets({
  envelope,
}: {
  envelope: DocumentEnvelope<ReportCardBatch>;
}) {
  const { branding, footer, body } = envelope;
  const total = body.cards.length;

  if (body.levelKind === "nursery") {
    return (
      <>
        {body.cards.map((card, index) => (
          <NurseryReportSheet
            key={card.studentId}
            branding={branding}
            footer={footer}
            batch={body}
            card={card}
            pageNumber={index + 1}
            pageCount={total}
          />
        ))}
      </>
    );
  }

  return (
    <>
      {body.cards.map((card, index) => (
        <ReportCardSheet
          key={card.studentId}
          branding={branding}
          footer={footer}
          batch={body}
          card={card}
          pageNumber={index + 1}
          pageCount={total}
        />
      ))}
    </>
  );
}

function ReportCardSheet({
  branding,
  footer,
  batch,
  card,
  pageNumber,
  pageCount,
}: {
  branding: Branding;
  footer: Footer;
  batch: ReportCardBatch;
  card: ReportCard;
  pageNumber: number;
  pageCount: number;
}) {
  const title = batch.isFinal
    ? "End of Term Report Card"
    : "Progress Report Card";

  const attendance =
    card.daysPresent !== null && card.daysPossible !== null && card.daysPossible > 0
      ? `${card.daysPresent} of ${card.daysPossible} days`
      : "—";

  return (
    <Sheet
      branding={branding}
      footer={footer}
      title={title}
      subtitle={`${batch.termName}  •  ${batch.academicYear}`}
      pageNumber={pageNumber}
      pageCount={pageCount}
    >
      <div className="rc-learner">
        {card.photoDataUrl && (
          <img className="rc-photo" src={card.photoDataUrl} alt="" />
        )}
        <div className="rc-fields">
          <Field label="Name" value={card.fullName} />
          <Field label="Reg. No." value={card.regNumber} />
          <Field
            label="Class"
            value={
              card.streamName ? `${card.className} — ${card.streamName}` : card.className
            }
          />
          <Field label="Sex" value={card.gender === "M" ? "Male" : card.gender === "F" ? "Female" : "—"} />
          <Field label="Term" value={batch.termName} />
          <Field label="Days present" value={attendance} />
        </div>
      </div>

      <table className="rc-table">
        <thead>
          <tr>
            <th className="left" style={{ width: "34%" }}>
              Subject
            </th>
            {batch.examNames.map((name) => (
              <th key={name}>{name}</th>
            ))}
            <th>Term</th>
            <th>Out of</th>
            <th>Grade</th>
            <th className="left" style={{ width: "18%" }}>
              Remark
            </th>
          </tr>
        </thead>
        <tbody>
          {card.subjects.map((subject) => (
            <tr key={subject.classSubjectId} className={subject.isCore ? "" : "non-core"}>
              <td className="subject">{subject.name}</td>
              {subject.examScores.map((score, index) => (
                <td key={index}>{score === null ? "—" : round(score)}</td>
              ))}
              <td>{subject.termScore === null ? "—" : round(subject.termScore)}</td>
              <td>{subject.maxScore}</td>
              <td className="grade">{subject.gradeLabel}</td>
              <td className="left">{subject.remark ?? ""}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <div className="rc-summary">
        {card.totalPoints !== null && (
          <div className="rc-summary-box">
            <div className="rc-summary-label">Aggregate</div>
            <div className="rc-summary-value">{round(card.totalPoints)}</div>
          </div>
        )}
        {card.division && (
          <div className="rc-summary-box">
            <div className="rc-summary-label">Division</div>
            <div className="rc-summary-value">{card.division}</div>
          </div>
        )}
        <div className="rc-summary-box">
          <div className="rc-summary-label">Average</div>
          <div className="rc-summary-value">
            {card.meanPercentage === null ? "—" : `${round(card.meanPercentage)}%`}
          </div>
        </div>
        <div className="rc-summary-box">
          <div className="rc-summary-label">Position</div>
          <div className="rc-summary-value">
            {card.position === null ? "—" : `${card.position} / ${card.classSize}`}
          </div>
        </div>
      </div>

      <div className="rc-comments">
        <div className="rc-comment">
          <div className="rc-comment-label">Class Teacher's comment</div>
          <div className="rc-comment-text">{card.classTeacherComment ?? ""}</div>
        </div>
        <div className="rc-comment">
          <div className="rc-comment-label">Headteacher's comment</div>
          <div className="rc-comment-text">{card.headTeacherComment ?? ""}</div>
        </div>
      </div>

      <div className="rc-signature">Headteacher's signature &amp; school stamp</div>
    </Sheet>
  );
}

// ---------------------------------------------------------------------------
// FR-D1 — the nursery report card
// ---------------------------------------------------------------------------

/** The five learning areas of the national ECCE framework. */
const LEARNING_AREAS: Record<string, string> = {
  "1": "Taking care of myself for proper growth and development",
  "2": "Interacting, exploring, knowing and using my environment",
  "3": "Relating with others in an acceptable way",
  "4": "Developing and using my language appropriately",
  "5": "Developing and using mathematical concepts in my day-to-day life",
};

function learningAreaNote(name: string): string | null {
  const match = /learning\s*area\s*(\d)/i.exec(name);
  return match ? LEARNING_AREAS[match[1]!] ?? null : null;
}

const RATING_LABEL: Record<Rating, string> = {
  excellent: "Excellent",
  very_good: "Very good",
  good: "Good",
  fair: "Fair",
  needs_help: "Needs help",
};

const RATING_ORDER: Rating[] = ["excellent", "very_good", "good", "fair", "needs_help"];

/** A picture for each activity, matched on its name. */
const ACTIVITY_ICONS: [RegExp, LucideIcon][] = [
  [/writ/i, PenLine],
  [/listen/i, Ear],
  [/read/i, BookOpen],
  [/speak|talk|oral/i, MessageCircle],
  [/draw|colou?r|paint|art/i, Palette],
  [/game|sport|play|physical/i, Volleyball],
  [/rhyme|stor|poem/i, Mic],
  [/music|sing|song|danc/i, Music],
  [/toilet/i, Toilet],
  [/health|hygien|clean|bath/i, HeartPulse],
  [/count|number|math/i, Calculator],
  [/shar|friend|relat/i, HandHeart],
  [/behav|conduct|manner/i, Smile],
  [/attend/i, Users],
  [/shape|puzzle|build/i, Puzzle],
  [/wash/i, Bath],
  [/craft|creat/i, Shapes],
];

function activityIcon(name: string): LucideIcon {
  return ACTIVITY_ICONS.find(([pattern]) => pattern.test(name))?.[1] ?? Star;
}

function formatDate(iso: string | null): string {
  if (!iso) return "";
  const date = new Date(`${iso.slice(0, 10)}T00:00:00`);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toLocaleDateString("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });
}

function NurseryReportSheet({
  branding,
  footer,
  batch,
  card,
  pageNumber,
  pageCount,
}: {
  branding: Branding;
  footer: Footer;
  batch: ReportCardBatch;
  card: ReportCard;
  pageNumber: number;
  pageCount: number;
}) {
  const ratings = new Map(card.activities.map((entry) => [entry.activity, entry.rating]));
  const absent =
    card.daysPresent !== null && card.daysPossible !== null
      ? card.daysPossible - card.daysPresent
      : null;
  const className = card.streamName
    ? `${card.className} — ${card.streamName}`
    : card.className;

  return (
    <Sheet
      branding={branding}
      footer={footer}
      variant="nursery"
      title={batch.isFinal ? "Learner's Assessment Report" : "Learner's Progress Report"}
      subtitle={`${batch.termName}  •  ${batch.academicYear}`}
      pageNumber={pageNumber}
      pageCount={pageCount}
      aside={
        card.photoDataUrl ? (
          <img className="nr-photo" src={card.photoDataUrl} alt="" />
        ) : (
          <div className="nr-photo nr-photo-empty">Photo</div>
        )
      }
    >
      <div className="nr-learner">
        <NField label="Name" value={card.fullName} wide />
        <NField label="Reg. No." value={card.regNumber} />
        <NField label="Class" value={className} />
        <NField
          label="Sex"
          value={card.gender === "M" ? "Male" : card.gender === "F" ? "Female" : "—"}
        />
        <NField label="Days attended" value={card.daysPresent?.toString() ?? "—"} />
        <NField label="Days absent" value={absent?.toString() ?? "—"} />
        <NField label="Days in term" value={card.daysPossible?.toString() ?? "—"} />
      </div>

      <div className="nr-columns">
        <section className="nr-panel">
          <h3 className="nr-heading">Achievement in the learning areas</h3>
          <table className="nr-table">
            <thead>
              <tr>
                <th className="left">Learning area</th>
                <th>Score</th>
                <th className="left">Remark</th>
              </tr>
            </thead>
            <tbody>
              {card.subjects.map((subject) => {
                const note = learningAreaNote(subject.name);
                return (
                  <tr key={subject.classSubjectId}>
                    <td className="left">
                      <div className="nr-area">{subject.name}</div>
                      {note && <div className="nr-area-note">{note}</div>}
                    </td>
                    <td className="nr-score">
                      {subject.termScore === null ? "—" : round(subject.termScore)}
                      <span className="nr-outof">/{subject.maxScore}</span>
                    </td>
                    <td className="left nr-remark">
                      {subject.termScore === null ? "" : subject.gradeLabel}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          <div className="nr-totals">
            <div>
              <span>Total</span>
              <strong>{round(card.totalMax)}</strong>
            </div>
            <div>
              <span>Scored</span>
              <strong>{card.totalScore === null ? "—" : round(card.totalScore)}</strong>
            </div>
            <div>
              <span>Position</span>
              <strong>
                {card.position === null ? "—" : `${card.position} of ${card.classSize}`}
              </strong>
            </div>
          </div>
        </section>

        <section className="nr-panel">
          <h3 className="nr-heading">Performance in learning activities</h3>
          <ul className="nr-activities">
            {batch.activityNames.map((activity, index) => {
              const Icon = activityIcon(activity);
              const rating = ratings.get(activity);
              return (
                <li key={activity} className="nr-activity">
                  <span className={`nr-activity-icon tint-${index % 6}`}>
                    <Icon size={15} strokeWidth={2.2} />
                  </span>
                  <span className="nr-activity-name">{activity}</span>
                  {rating ? (
                    <span className={`nr-rating rating-${rating}`}>
                      <RatingStars rating={rating} />
                      {RATING_LABEL[rating]}
                    </span>
                  ) : (
                    <span className="nr-rating nr-rating-blank" />
                  )}
                </li>
              );
            })}
          </ul>
        </section>
      </div>

      <table className="nr-comments">
        <tbody>
          <tr>
            <th>Class Teacher's report</th>
            <td>{card.classTeacherComment ?? ""}</td>
            <td className="nr-sign">
              {card.classTeacherName ?? ""}
              <span>Signature</span>
            </td>
          </tr>
          <tr>
            <th>Behaviour and cleanliness</th>
            <td colSpan={2}>{card.conductComment ?? ""}</td>
          </tr>
          <tr>
            <th>Headteacher's comment</th>
            <td>{card.headTeacherComment ?? ""}</td>
            <td className="nr-sign">
              {batch.headTeacherName ?? ""}
              <span>Signature</span>
            </td>
          </tr>
        </tbody>
      </table>

      <div className="nr-foot">
        <div className="nr-foot-facts">
          <div>
            <span>Date of issue</span>
            <strong>{footer.printedOn}</strong>
          </div>
          <div>
            <span>Next term begins</span>
            <strong>{formatDate(batch.nextTermBegins) || "\u00a0"}</strong>
          </div>
          <div className="nr-requirements">
            <span>School requirements</span>
            <strong>{batch.requirements ?? "\u00a0"}</strong>
          </div>
        </div>
        <div className="nr-stamp">School stamp</div>
      </div>
    </Sheet>
  );
}

/** Stars as well as a word, so a rating reads without colour. */
function RatingStars({ rating }: { rating: Rating }) {
  const filled = RATING_ORDER.length - RATING_ORDER.indexOf(rating);
  return (
    <span className="nr-stars" aria-hidden="true">
      {"★".repeat(filled)}
      <span className="nr-stars-empty">{"★".repeat(RATING_ORDER.length - filled)}</span>
    </span>
  );
}

function NField({ label, value, wide }: { label: string; value: string; wide?: boolean }) {
  return (
    <div className={wide ? "nr-field nr-field-wide" : "nr-field"}>
      <span className="nr-field-label">{label}</span>
      <span className="nr-field-value">{value}</span>
    </div>
  );
}

function Field({ label, value }: { label: string; value: string }) {
  return (
    <div className="rc-field">
      <span className="rc-field-label">{label}</span>
      <span className="rc-field-value">{value}</span>
    </div>
  );
}

// ---------------------------------------------------------------------------
// FR-G16 — student and staff ID cards
// ---------------------------------------------------------------------------

/** Eight cards to an A4 page: two across, four down, with room to cut. */
const CARDS_PER_SHEET = 8;

export type IdCardFormat = "sheet" | "printer";

/**
 * Every card carries the school's own name, logo, colour and contacts from
 * the same branding envelope as every other document (FR-D4).
 *
 * `sheet` prints eight to an A4 page inside the usual header and footer, for
 * cutting and laminating. `printer` prints one card per page at the standard
 * 85.6 × 54 mm size for a PVC card printer; a card that size has no room for
 * the A4 footer, so its only marks are the school's.
 */
export function IdCardSheets({
  envelope,
  format,
}: {
  envelope: DocumentEnvelope<IdCardBatch>;
  format: IdCardFormat;
}) {
  const { branding, footer, body } = envelope;

  if (format === "printer") {
    return (
      <>
        <style>{"@page { size: 85.6mm 54mm; margin: 0; }"}</style>
        <div className="idc-printer">
          {body.cards.map((card) => (
            <div key={card.id} className="idc-page">
              <IdCardFace branding={branding} batch={body} card={card} />
            </div>
          ))}
        </div>
      </>
    );
  }

  const pages: IdCard[][] = [];
  for (let start = 0; start < body.cards.length; start += CARDS_PER_SHEET) {
    pages.push(body.cards.slice(start, start + CARDS_PER_SHEET));
  }
  const who = body.kind === "staff" ? "Staff" : "Learner";

  return (
    <>
      {pages.map((cards, index) => (
        <Sheet
          key={index}
          branding={branding}
          footer={footer}
          variant="compact"
          title={`${who} ID cards`}
          subtitle={[
            body.kind === "student" ? cards[0]?.title : null,
            body.academicYear,
            "Cut along the dashed lines",
          ]
            .filter(Boolean)
            .join("  •  ")}
          pageNumber={index + 1}
          pageCount={pages.length}
        >
          <div className="idc-grid">
            {cards.map((card) => (
              <div key={card.id} className="idc-cut">
                <IdCardFace branding={branding} batch={body} card={card} />
              </div>
            ))}
          </div>
        </Sheet>
      ))}
    </>
  );
}

function initials(name: string): string {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]!.toUpperCase())
    .join("");
}

function IdCardFace({
  branding,
  batch,
  card,
}: {
  branding: Branding;
  batch: IdCardBatch;
  card: IdCard;
}) {
  const isStaff = batch.kind === "staff";
  const contact = [branding.phone, branding.address].filter(Boolean).join("  •  ");
  const validUntil = batch.validUntil ? formatDate(batch.validUntil) : null;

  return (
    <div
      className="idc"
      style={{ "--doc-accent": branding.accentColor } as CSSProperties}
    >
      <div className="idc-band">
        {branding.logoDataUrl ? (
          <img className="idc-logo" src={branding.logoDataUrl} alt="" />
        ) : (
          <span className="idc-logo idc-logo-blank">{initials(branding.institutionName)}</span>
        )}
        <div className="idc-school">
          <div className="idc-school-name">{branding.institutionName}</div>
          {branding.motto && <div className="idc-motto">“{branding.motto}”</div>}
        </div>
        <span className="idc-kind">{isStaff ? "Staff" : "Learner"}</span>
      </div>

      <div className="idc-body">
        {card.photoDataUrl ? (
          <img className="idc-photo" src={card.photoDataUrl} alt="" />
        ) : (
          <span className="idc-photo idc-photo-blank">{initials(card.fullName)}</span>
        )}
        <div className="idc-info">
          <div className="idc-name">{card.fullName}</div>
          <div className="idc-title">
            {card.title}
            {card.detail ? ` • ${card.detail}` : ""}
          </div>
          <dl className="idc-facts">
            <dt>{isStaff ? "Staff ID" : "Reg. No."}</dt>
            <dd className="idc-number">{card.number}</dd>
            {card.dateOfBirth && (
              <>
                <dt>Born</dt>
                <dd>{formatDate(card.dateOfBirth)}</dd>
              </>
            )}
            {card.contact && (
              <>
                <dt>{isStaff ? "Phone" : "Guardian"}</dt>
                <dd>{card.contact}</dd>
              </>
            )}
          </dl>
        </div>
      </div>

      <div className="idc-foot">
        <span className="idc-contact">{contact}</span>
        {batch.academicYear && (
          <span className="idc-valid">
            {validUntil ? `Valid until ${validUntil}` : `Valid ${batch.academicYear}`}
          </span>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// FR-G22 — the pass-out slip
// ---------------------------------------------------------------------------

function slipTime(iso: string | null): string {
  if (!iso) return "";
  return new Date(iso).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
}

/**
 * Two copies on one A4 page, cut apart: the learner carries the gate copy out,
 * the school keeps the other.
 */
export function PassOutSlipSheet({ envelope }: { envelope: DocumentEnvelope<PassOutSlip> }) {
  const { branding, footer, body } = envelope;
  const number = `PO-${String(body.number).padStart(4, "0")}`;
  const date = new Date(body.timeOut).toLocaleDateString("en-GB", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  return (
    <Sheet
      branding={branding}
      footer={footer}
      variant="compact"
      title="Learner Pass-Out"
      subtitle={`${number}  •  ${date}`}
      pageNumber={1}
      pageCount={1}
    >
      <div
        className="po-sheet"
        style={{ "--doc-accent": branding.accentColor } as CSSProperties}
      >
        <PassOutCopy slip={body} number={number} copy="Gate copy" note="Show this slip at the gate." />
        <div className="po-cut">
          <span>Cut here</span>
        </div>
        <PassOutCopy slip={body} number={number} copy="School copy" note="Keep in the pass-out file." />
      </div>
    </Sheet>
  );
}

function PassOutCopy({
  slip,
  number,
  copy,
  note,
}: {
  slip: PassOutSlip;
  number: string;
  copy: string;
  note: string;
}) {
  const withWhom = [
    slip.pickedUpBy,
    slip.pickedUpRelationship ? `(${slip.pickedUpRelationship})` : null,
    slip.pickedUpPhone,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <section className="po-copy">
      <header className="po-copy-head">
        <span className="po-copy-kind">{copy}</span>
        <span className="po-copy-number">{number}</span>
      </header>

      <div className="po-copy-body">
        {slip.photoDataUrl ? (
          <img className="po-photo" src={slip.photoDataUrl} alt="" />
        ) : (
          <span className="po-photo po-photo-blank">{initials(slip.studentName)}</span>
        )}

        <div className="po-details">
          <div className="po-name">{slip.studentName}</div>
          <div className="po-sub">
            {slip.className}  •  {slip.regNumber}
          </div>

          <dl className="po-facts">
            <dt>Reason</dt>
            <dd>
              {slip.reasonLabel}
              {slip.reason ? ` — ${slip.reason}` : ""}
            </dd>
            <dt>Going to</dt>
            <dd>{slip.destination ?? "—"}</dd>
            <dt>With</dt>
            <dd>{withWhom || "—"}</dd>
          </dl>
        </div>

        <div className="po-times">
          <div className="po-time">
            <span>Time out</span>
            <strong>{slipTime(slip.timeOut)}</strong>
          </div>
          <div className="po-time po-time-back">
            <span>Expected back</span>
            <strong>{slip.expectedBack ? slipTime(slip.expectedBack) : "Not today"}</strong>
          </div>
        </div>
      </div>

      <footer className="po-copy-foot">
        <div className="po-sign">
          {slip.issuedByName ?? ""}
          <span>Issued by</span>
        </div>
        <div className="po-sign">
          <span>Guardian's signature</span>
        </div>
        <div className="po-sign">
          <span>Gate: time and guard's signature</span>
        </div>
      </footer>
      <div className="po-note">
        {note}
        {slip.guardianTexted ? " The guardian has been sent an SMS." : ""}
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------
// FR-D2 — class list
// ---------------------------------------------------------------------------

export function ClassListSheet({
  envelope,
}: {
  envelope: DocumentEnvelope<ClassListBody>;
}) {
  const { branding, footer, body } = envelope;

  return (
    <Sheet
      branding={branding}
      footer={footer}
      title="Class List"
      subtitle={
        body.termName
          ? `${body.className}  •  ${body.termName}  •  ${body.academicYear}`
          : `${body.className}  •  ${body.academicYear}`
      }
      pageNumber={1}
      pageCount={1}
    >
      <table className="cl-table">
        <thead>
          <tr>
            <th className="num">#</th>
            <th style={{ width: "22%" }}>Reg. No.</th>
            <th>Name</th>
            <th style={{ width: "8%" }}>Sex</th>
            <th style={{ width: "22%" }}>Guardian</th>
            <th style={{ width: "18%" }}>Phone</th>
          </tr>
        </thead>
        <tbody>
          {body.rows.map((row) => (
            <tr key={row.regNumber}>
              <td className="num">{row.number}</td>
              <td>{row.regNumber}</td>
              <td>{row.fullName}</td>
              <td>{row.gender ?? "—"}</td>
              <td>{row.guardianName ?? "—"}</td>
              <td>{row.guardianPhone ?? "—"}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <div className="cl-totals">
        <span>Total: {body.total}</span>
        <span>Boys: {body.boys}</span>
        <span>Girls: {body.girls}</span>
      </div>
    </Sheet>
  );
}

function round(value: number): string {
  return Number.isInteger(value) ? String(value) : value.toFixed(1);
}
